    memcpy(buf, D_800892C0, 5);
    func_80069E38(buf, p + 0x34);
    func_80069E38(buf, (u8 *)D_8008933C);
    func_80069E38(buf, func_800B5D30(p));
    func_800B5264(b[4], buf, 0, 0x47, 0x88);
