        *(u8 *)0x800133A7 = v;
        break;
    case 10:
    case 44:
        *(u8 *)0x800133A7 = v;
        break;
    case 17:
    case 18:
        *(u8 *)0x800133A9 = v;
        break;
    case 56:
        v = 3;
        *(u8 *)0x800133BB = v;
        break;
    case 1:
    case 2:
    case 3:
    case 64:
    case 65:
    case 66:
        *(u8 *)0x800133BB = v;
        break;
    case 57:
        v = 2;
        *(u8 *)0x800133BB = v;
        break;
    case 63:
        v = 1;
        *(u8 *)0x800133BB = v;
        break;
    case 4:
    case 5:
        *(u8 *)0x800133C5 = v;
        break;
    case 15:
    case 16:
        *(u8 *)0x800133C7 = v;
        break;
    case 7:
    case 45:
